def frame(kind,formula,caption,why,**data):
 return dict(nodes=[],edges=[],snapshot=dict(kind=kind,**data),caption=caption,captionMathHtml=prose(caption),formula=formula,formulaHtml=mathml.render(formula,True),metrics={},line=0,teaching=dict(operation=caption,operationHtml=prose(caption),why=why,whyHtml=prose(why),currentState={},initial=False,activeLine=0,changes=[],checks=[]))
def scene(name,title,description,frames,guide=None):
 guide=guide or ['Read the fixed input and the exact counting domain.','Apply the stated arithmetic condition to the current candidate.','Verify the final result and the completeness argument.']
 for i,f in enumerate(frames):
  f['line']=0 if i==0 else 2 if i==len(frames)-1 else 1;f['teaching'].update(initial=i==0,activeLine=f['line'],guide=guide,currentState={'Checkpoint':i,'Total checkpoints':len(frames)})
  if i:f['teaching']['changes']=[dict(field='Checkpoint',before=i-1,after=i)]
 id='discrete-number-question-'+name;S[id]=dict(id=id,title=title,description=description,descriptionHtml='<p>'+prose(description)+'</p>',invariant=description,visual=dict(type='enumeration',claim=description),code=guide,frames=frames,useAuthoredTeachingChanges=True)
 if len(frames)>12:S[id]['printFrameIndices']=[0,1,len(frames)//2,len(frames)-1]
def table(name,title,heads,rows,formulas,why,description):
 fs=[]
 for i in range(len(rows)):
  visible=rows[max(0,i-6):i+1];cell=lambda s:mathml.render(str(s)[1:],False)if str(s).startswith('$')else html.escape(str(s))
  fs.append(frame('table',formulas[i]if isinstance(formulas,list)else formulas,'Read exact row $'+str(i)+'$ of this arithmetic ledger.',why,headings=heads,rows=rows[:i+1],rowsHtml=[[cell(s)for s in row]for row in visible],active=len(visible)-1))
 scene(name,title,description,fs)
