def crt(name,m,n,r,s):
 L=math.lcm(m,n);pairs=[(x%m,x%n,x)for x in range(L)];target=[x for a,b,x in pairs if a==r%m and b==s%n];fs=[]
 for k in [0,1,L//2,L]:
  formula=rf'x_0={target[0]},\quad L={L}'if k==L and target else rf'x\equiv{r}\pmod{{{m}}},\quad x\equiv{s}\pmod{{{n}}}'
  fs.append(frame('crt-grid',formula,f'Classify the first ${k}$ canonical residues modulo ${L}$.','Each occupied coordinate cell corresponds to exactly one residue modulo the lcm. Empty cells are incompatible coordinate pairs; the target cell is highlighted only if it exists. A row window is labeled and all windows remain available through checkpoints.',m=m,n=n,pairs=pairs,inspected=k,target=[r%m,s%n],answers=target,period=L))
 scene(name,'CRT coordinates: moduli '+str(m)+' and '+str(n),'The grid isolates the common-gcd residue of the target and shows every compatible coordinate in that block. Other shared-residue blocks are explicitly separate; no full Cartesian product is presumed for overlapping moduli.',fs)
crt('shared',8,6,5,1);crt('deadline',12,18,5,11)
