 for k in range(limit+1):fs.append(frame('power-orbit',rf'{a}^{{{k}}}\equiv{values[k]}\pmod{{{m}}}',f'Exponent ${k}$ has exact residue ${values[k]}$.','The connected sequence uses increasing exponents; repeated residues identify a return, while the written proof establishes the range over which the period is valid.',a=a,m=m,values=values,active=k))
 scene(name,'Power sequence: base '+str(a)+' modulo '+str(m),'Exponent zero is shown separately; subsequent arrows are actual multiplication by the fixed base.',fs)
